function selectTool(t){if(t&&buildMode!=='build')setBuildMode('build');if(walkMode)exitWalk();tool=t;selected=null;$('tilePanel').hidden=true;$('inspectButton').classList.toggle('active',!t&&buildMode==='build');document.querySelectorAll('.tool').forEach(b=>{b.classList.toggle('active',b.dataset.tool===t);b.setAttribute('aria-pressed',String(b.dataset.tool===t))});canvas.classList.toggle('building',!!t);$('toolDescription').textContent=t?CATALOG[t].description:'Select a construction tool, then choose a block.';$('toolCost').textContent=t?(CATALOG[t].cost?'$'+CATALOG[t].cost.toLocaleString()+' / block':'25% refund'):'1–9: tools · B: bulldoze';updateHighlight()}
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3800)}
function save(){try{localStorage.setItem('blockhaven-city',JSON.stringify(city));$('saveStatus').textContent='● Saved on this device';dirty=false;return true}catch{$('saveStatus').textContent='Save unavailable · export to keep your city';return false}}
function changed(){dirty=true;$('saveStatus').textContent='● Saving…'}
function updateUI(){const m=metrics(city);$('money').textContent=(city.money<0?'−':'')+'$'+Math.abs(Math.floor(city.money)).toLocaleString();$('income').textContent=(m.income>=0?'+':'−')+'$'+Math.abs(m.income).toLocaleString()+' / day';$('income').style.color=m.income>=0?'#608b6d':'#a76754';$('population').textContent=m.pop.toLocaleString();$('happiness').textContent=m.happiness+'%';$('day').textContent='Day '+city.day;$('season').textContent=['Spring','Summer','Autumn','Winter'][Math.floor((city.day-1)/30)%4]+', year '+(1+Math.floor((city.day-1)/120));$('cityName').value=city.name;$('level').textContent=m.pop>=2500?'A thriving coastal city':m.pop>=1500?'A growing town':m.pop>=750?'Town':'Coastal village';const goal=[750,1500,2500].find(v=>!city.grants.includes(v));$('goalTitle').textContent=goal===750?'Establish a neighborhood':goal===1500?'Expand the town':goal===2500?'Build a coastal city':'Development complete';$('goalCopy').textContent=goal?`Grow to ${goal.toLocaleString()} residents. Keep homes connected, provide jobs, and look after your people.`:'All population milestones reached. Keep shaping your coast.';$('goalCount').textContent=goal?m.pop.toLocaleString()+' / '+goal.toLocaleString():m.pop.toLocaleString();$('goalProgress').style.width=(goal?Math.min(100,m.pop/goal*100):100)+'%';$('goalReward').textContent=goal?'◈ $3,000 milestone grant':'✦ A city worth calling home';if(selected)showTile(...selected);updateDashboard()}
function showTile(x,y){selected=[x,y];const t=at(city,x,y),c=CATALOG[t?.type];$('tilePanel').hidden=false;$('toggleBuilding').hidden=!t?.type||['road','hall','home'].includes(t.type);$('toggleBuilding').textContent=t?.enabled===false?'Switch on':'Switch off';$('operationStatus').textContent=t?.enabled===false?'Switched off · no jobs, coverage or upkeep':'';$('tileName').textContent=c?.name||(t?.type==='hall'?'Town Hall':land(x,y,city.terrain)?'Open land':'Coastal water');$('tileIcon').textContent=t?.type==='home'?'⌂':t?.type==='park'?'♧':t?.type==='road'?'═':t?.type==='hall'?'⚑':'▦';$('tileInfo').textContent=c?.description||(t?.type==='hall'?'The heart of your city. All roads should lead back to its network.':'Choose a construction tool to shape this part of your city.');if(t?.type==='home'||c?.jobs||['school','clinic'].includes(t?.type)){const a=status(city,x,y,metrics(city).roads);$('tileDetails').innerHTML=`${t.type==='home'?`Residents: ${t.pop} / ${a.capacity}<br>`:''}${c?.jobs?`Jobs: ${a.road&&a.power&&a.water&&t.enabled!==false?c.jobs:0} / ${c.jobs}<br>`:''}${a.road?'✓':'○'} Connected road<br>${a.power?'✓':'○'} Electricity<br>${a.water?'✓':'○'} Fresh water${t.type==='home'?`<br>${a.park?'✓':'○'} Park nearby<br>${a.school?'✓':'○'} School nearby<br>${a.clinic?'✓':'○'} Healthcare<br>${a.fire?'✓':'○'} Fire protection<br>${a.police?'✓':'○'} Safety${a.polluted?'<br>⚠ Workshop pollution nearby':''}`:''}`}else $('tileDetails').textContent=c?.upkeep?'Upkeep: $'+c.upkeep+' / day':t?.zone?'Zoned '+CATALOG[t.zone].name.toLowerCase()+'. Develops with a connected road, electricity and water.':''}
function perform(x,y,quiet=false){if(walkMode)return;if(buildMode==='zone'){const previous={...at(city,x,y)},balance=city.money;const result=zone(city,x,y,zoneType,districtStyle,{density:$('densitySelect').value});if(result.error){if(!quiet)toast(result.error);return}undoStack.push({x,y,tile:previous,delta:balance-city.money});createBlock(x,y);changed();updateUI();updateLayer();tourAction('zone',x,y);if(!quiet)toast('District zoned. Connected blocks develop as time runs.');return}if(!tool){showTile(x,y);tourAction('inspect',x,y);return}const previous={...at(city,x,y)},balance=city.money;const result=build(city,x,y,tool,districtStyle,{roadKind:$('roadSelect').value,density:$('densitySelect').value});if(result.error){if(!quiet)toast(result.error);return}undoStack.push({x,y,tile:previous,delta:balance-city.money});if(undoStack.length>60)undoStack.shift();if(tool==='demolish'){const[px,pz]=pos(x,y);visual.particles(px,2,pz,'dust',22)}createBlock(x,y,true);if(tool==='road'||tool==='demolish'){for(const[a,b]of [[1,0],[-1,0],[0,1],[0,-1]])if(at(city,x+a,y+b)?.type==='road')createBlock(x+a,y+b);makeCars()}changed();updateUI();updateLayer();tourAction(tool,x,y);if(!quiet)toast(tool==='demolish'?'Block cleared. 25% refunded.':CATALOG[tool].name+' built.');updateHighlight()}
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),hit=new THREE.Vector3(),groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0);let width,height;
function tileAt(e){const r=canvas.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(pointer,camera);if(!raycaster.ray.intersectPlane(groundPlane,hit))return null;const x=Math.floor(hit.x/10+N/2),y=Math.floor(hit.z/10+N/2);return x>=0&&x<N&&y>=0&&y<N?[x,y]:null}
function updateHighlight(){if(!hover||walkMode){tileHighlight.visible=false;return}const[x,y]=hover;tileHighlight.visible=land(x,y,city.terrain);const[px,pz]=pos(x,y);tileHighlight.position.set(px,.55,pz);tileHighlight.material.color.set(tool?(tool==='demolish'?'#e4a97e':at(city,x,y)?.type?'#c98066':'#dfdf9e'):'#e8d8a8')}
let drag=null;const pointers=new Map();let pinch=0;
canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const p=[...pointers.values()];pinch=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)}drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false,button:e.button,lastTile:null};if(e.shiftKey&&(tool||buildMode==='zone')){const t=tileAt(e);if(t){perform(...t,true);drag.lastTile=t.join(',')}}});
canvas.addEventListener('pointermove',e=>{hover=tileAt(e);updateHighlight();if(!drag)return;if(pointers.has(e.pointerId))pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const p=[...pointers.values()],d=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);distance=Math.max(90,Math.min(650,distance*pinch/d));pinch=d;drag.moved=true;return}const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.moved ||= Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>5;if(e.shiftKey&&(tool||buildMode==='zone')&&hover){const k=hover.join(',');if(k!==drag.lastTile){perform(...hover,true);drag.lastTile=k}}else if(drag.moved){if(walkMode){walkYaw-=dx*.006;walkPitch=THREE.MathUtils.clamp(walkPitch-dy*.004,-.55,.55)}else if(drag.button===2){azimuth-=dx*.006;elevation=Math.max(.3,Math.min(1.3,elevation+dy*.005))}else{const scale=distance/height*.62;target.x+=(-dx*Math.cos(azimuth)-dy*Math.sin(azimuth))*scale;target.z+=(dx*Math.sin(azimuth)-dy*Math.cos(azimuth))*scale;target.x=THREE.MathUtils.clamp(target.x,-160,160);target.z=THREE.MathUtils.clamp(target.z,-160,160)}}drag.x=e.clientX;drag.y=e.clientY});
canvas.addEventListener('pointerup',e=>{pointers.delete(e.pointerId);if(drag&&!drag.moved&&drag.button===0&&!e.shiftKey){const t=tileAt(e);if(t&&!walkMode)perform(...t)}drag=null});canvas.addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);drag=null});canvas.addEventListener('pointerleave',()=>{hover=null;updateHighlight()});canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('wheel',e=>{e.preventDefault();distance=Math.max(90,Math.min(650,distance*Math.exp(e.deltaY*.001)));},{passive:false});
function center(){target.set(width<720?-10:-24,0,0);distance=width<720?290:width<1100?270:225;azimuth=.8;elevation=.62}function resize(){width=innerWidth;height=$('game').clientHeight;renderer.setSize(width,height,false);camera.aspect=width/height;camera.updateProjectionMatrix()}addEventListener('resize',resize);resize();center();
$('zoomIn').onclick=()=>distance=Math.max(90,distance*.83);$('zoomOut').onclick=()=>distance=Math.min(650,distance*1.2);$('recenter').onclick=center;$('gridButton').onclick=()=>{gridVisible=!gridVisible;grid.visible=gridVisible;$('gridButton').setAttribute('aria-pressed',String(gridVisible))};$('inspectButton').onclick=()=>selectTool(null);$('closeTile').onclick=()=>{selected=null;$('tilePanel').hidden=true};$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Resume simulation':'Pause simulation')};document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=Number(b.dataset.speed);document.querySelectorAll('[data-speed]').forEach(v=>v.classList.toggle('active',v===b));if(paused)$('pause').click()});
$('menuHelpButton').onclick=()=>{$('menuDialog').close();$('helpDialog').showModal()};$('menuButton').onclick=()=>{updateSaveSlots();$('menuDialog').showModal()};$('helpButton').onclick=startTour;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('dismissGuide').onclick=()=>$('guide').hidden=true;$('rename').onclick=()=>{$('cityName').focus();$('cityName').select()};$('cityName').addEventListener('change',()=>{city.name=$('cityName').value.trim()||'New Port';changed();updateUI()});$('cityName').addEventListener('keydown',e=>{if(e.key==='Enter')e.target.blur()});$('saveButton').onclick=()=>{if(save())toast('City saved on this device.')};$('exportButton').onclick=()=>{const blob=new Blob([JSON.stringify(city,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=city.name.replace(/[^a-z0-9_-]/gi,'-')+'.blockhaven.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('City exported. Keep this file to restore it later.')};$('importFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1e6)throw Error('too large');const next=validateCity(JSON.parse(await f.text()));city=next;undoStack.length=0;rebuild();save();$('menuDialog').close();toast('Welcome back to '+city.name+'.')}catch{toast('That file is not a valid Blockhaven city. Choose an exported .json file.')}e.target.value=''};$('newButton').onclick=()=>{$('menuDialog').close();$('newDialog').showModal()};$('confirmNew').onclick=()=>{if(tourActive)finishTour(false);city=newCity($('terrainSelect').value);undoStack.length=0;elapsed=0;rebuild();center();save();$('newDialog').close();startTour()};
addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||document.querySelector('dialog[open]'))return;const key=e.key.toLowerCase();if((e.ctrlKey||e.metaKey)&&key==='z'){e.preventDefault();undoBuild();return}if(walkMode){if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(key)){e.preventDefault();heldKeys.add(key)}if(key==='escape')exitWalk();return}if(key==='escape'){setBuildMode('build');selectTool(null);}if(key===' '){e.preventDefault();$('pause').click()}const t=Object.keys(CATALOG).find(k=>CATALOG[k].key.toLowerCase()===key);if(t)selectTool(t)});addEventListener('beforeunload',save);setInterval(()=>{if(dirty)save()},8000);
