function persistSettings(){try{localStorage.setItem('blockhaven-settings',JSON.stringify(settings))}catch{toast('Settings could not be saved on this device.')}}
function setBuildMode(mode){buildMode=mode;$('buildModeButton').classList.toggle('active',mode==='build');$('zoneModeButton').classList.toggle('active',mode==='zone');$('zoneOptions').hidden=mode!=='zone';if(mode==='zone'){selectTool(null);canvas.classList.add('building');$('toolDescription').textContent='Paint open blocks. Developers build along connected roads with power and water.';$('toolCost').textContent='$20 / zoned block'}else if(!tool)canvas.classList.remove('building')}
function undoBuild(){const action=undoStack.pop();if(!action){toast('No construction to undo in this session.');return}city.grid[action.y*N+action.x]={...action.tile};city.money+=action.delta;createBlock(action.x,action.y);for(const[a,b]of [[1,0],[-1,0],[0,1],[0,-1]])if(at(city,action.x+a,action.y+b)?.type==='road')createBlock(action.x+a,action.y+b);makeCars();changed();updateUI();updateLayer();toast('Last construction undone.')}
const overlay=new THREE.InstancedMesh(new THREE.BoxGeometry(9.6,.1,9.6),new THREE.MeshBasicMaterial({transparent:true,opacity:.43,depthWrite:false}),N*N);overlay.visible=false;overlay.renderOrder=2;scene.add(overlay);const overlayMatrix=new THREE.Matrix4(),overlayColor=new THREE.Color();
function updateLayer(){overlay.visible=activeLayer!=='none';$('layerLegend').hidden=activeLayer==='none';if(activeLayer==='none')return;const m=metrics(city);let count=0;for(let y=0;y<N;y++)for(let x=0;x<N;x++)if(land(x,y,city.terrain)){const a=status(city,x,y,m.roads),good=activeLayer==='polluted'?!a.polluted:a[activeLayer];const[px,pz]=pos(x,y);overlayMatrix.makeTranslation(px,.5,pz);overlay.setMatrixAt(count,overlayMatrix);overlay.setColorAt(count,overlayColor.set(good?'#6da17b':'#c97f63'));count++}overlay.count=count;overlay.instanceMatrix.needsUpdate=true;overlay.instanceColor.needsUpdate=true;overlay.computeBoundingSphere();$('layerName').textContent=$('layerSelect').selectedOptions[0].textContent;$('layerGoodText').textContent=activeLayer==='polluted'?'Low pollution':'Supplied';$('layerBadText').textContent=activeLayer==='polluted'?'Polluted':'Missing'}
function updateDashboard(){if(!$('reportSummary'))return;const m=metrics(city);$('reportSummary').innerHTML=`<div><strong>${m.pop.toLocaleString()}</strong>Residents</div><div><strong>${m.jobs.toLocaleString()}</strong>Active jobs</div><div><strong>${m.happiness}%</strong>Happiness</div>`;$('taxSlider').value=city.taxRate??9;document.querySelectorAll('[data-tax]').forEach(e=>{e.value=city.zoneTaxes?.[e.dataset.tax]??city.taxRate??9;e.nextElementSibling.textContent=e.value+'%'});document.querySelectorAll('[data-funding]').forEach(e=>{e.value=city.funding?.[e.dataset.funding]??100;e.nextElementSibling.textContent=e.value+'%'});$('loanStatus').textContent=city.loan?.daysLeft>0?`$${city.loan.remaining.toLocaleString()} remaining · ${city.loan.daysLeft} days · $1,400 / day`:'Borrow $25,000. Repay $28,000 over 20 days at $1,400 per day.';$('loanButton').disabled=!!city.loan?.daysLeft;$('taxValue').textContent=(city.taxRate??9)+'%';const cash=v=>(v<0?'−':'')+'$'+Math.abs(Math.floor(v)).toLocaleString();$('budgetRows').innerHTML=`<div><span>Residential tax</span><b class="positive">+${cash(m.residentialTax)}</b></div><div><span>Business tax</span><b class="positive">+${cash(m.businessTax)}</b></div><div><span>Roads, buildings and services</span><b class="negative">−${cash(m.upkeep)}</b></div><div><span>Loan payment</span><b class="negative">−${cash(m.loanPayment)}</b></div><div class="total"><span>Net income / day</span><b class="${m.income>=0?'positive':'negative'}">${cash(m.income)}</b></div>`;$('demandBars').innerHTML=Object.entries(m.demand).map(([k,v])=>`<div class="demand-row">${k==='home'?'Residential':k==='shop'?'Commercial':'Industrial'}<span>${v}%</span><div class="demand-track"><i style="width:${v}%"></i></div></div>`).join('');const homes=city.grid.map((t,i)=>t.type==='home'?status(city,i%N,Math.floor(i/N),m.roads):null).filter(Boolean);$('serviceRows').innerHTML=Object.entries({road:'Connected streets',power:'Electricity',water:'Fresh water',school:'Education',clinic:'Healthcare',fire:'Fire protection',police:'Safety',park:'Green space'}).map(([k,label])=>{const n=homes.filter(a=>a[k]).length;return `<div class="service-row"><span>${label}</span><b>${n} / ${homes.length} homes</b></div>`}).join('');const notes=[];if(m.jobs*2<=m.pop)notes.push('Growth is limited by jobs. Add connected shops, offices or workshops with power and water.');if(m.housing<=m.pop+20)notes.push('Housing is nearly full. Add homes or zone a residential district.');if(homes.some(a=>!a.road))notes.push('Some homes have no connected road. Use the Road access layer to find them.');if(homes.some(a=>!a.power||!a.water))notes.push('Some homes need utilities. Check the electricity and water layers, then extend coverage.');if(m.happiness<50)notes.push('Happiness is low. Reduce high taxes, add parks and services, and separate homes from industry.');if(m.income<0)notes.push('Daily upkeep exceeds tax income. Expand active businesses or remove services you do not need.');if(!notes.length)notes.push('Your city has a stable foundation. Expand streets, zone new districts and keep an eye on service coverage.');$('advisorNotes').innerHTML=notes.map(n=>`<p class="advisor-note">${n}</p>`).join('');const history=city.history??[];if(history.length){const max=Math.max(1,...history.map(h=>h.pop)),points=history.map((h,i)=>`${10+i/Math.max(1,history.length-1)*380},${120-h.pop/max*105}`).join(' ');$('populationChart').innerHTML=`<polyline points="${points}" fill="none" stroke="#6f947d" stroke-width="3"/><text x="10" y="12" fill="#7c8f80" font-size="9">${max.toLocaleString()} residents</text>`;$('historyRows').innerHTML=history.slice(-10).reverse().map(h=>`<div>Day ${h.day} · ${h.pop.toLocaleString()} residents · ${cash(h.income)} / day</div>`).join('')}else{$('populationChart').innerHTML='<text x="20" y="70" fill="#7c8f80" font-size="12">Let time run to record your city’s growth.</text>';$('historyRows').textContent='A new data point is recorded each simulation day.'}}
