function enterWalk(){if(tourActive)finishTour(false);const road=city.grid.findIndex((t,i)=>t.type==='road'&&Math.hypot(i%N-15,Math.floor(i/N)-15)<5);if(road<0){toast('Build a road before taking a walk.');return}selectTool(null);setBuildMode('build');walkMode=true;const[x,z]=pos(road%N,Math.floor(road/N));walkPosition.set(x,2.3,z);walkYaw=.8;walkPitch=0;$('walkControls').hidden=false;$('game').classList.add('walking');toast('Welcome to street level. WASD to walk; drag to look.');heldKeys.clear()}
function exitWalk(){walkMode=false;heldKeys.clear();$('walkControls').hidden=true;$('game').classList.remove('walking')}
function updateWalking(dt,modal){if(modal)return;const forward=(heldKeys.has('w')||heldKeys.has('arrowup')?1:0)-(heldKeys.has('s')||heldKeys.has('arrowdown')?1:0),side=(heldKeys.has('d')||heldKeys.has('arrowright')?1:0)-(heldKeys.has('a')||heldKeys.has('arrowleft')?1:0),length=Math.hypot(forward,side)||1;const dx=(Math.sin(walkYaw)*forward-Math.cos(walkYaw)*side)/length*dt*7,dz=(Math.cos(walkYaw)*forward+Math.sin(walkYaw)*side)/length*dt*7;function allowed(x,z){const tx=Math.floor(x/10+N/2),ty=Math.floor(z/10+N/2),t=at(city,tx,ty);return !!t&&(land(tx,ty,city.terrain)||t.roadKind==='bridge')&&(!t.type||['road','park'].includes(t.type))}if(allowed(walkPosition.x+dx,walkPosition.z))walkPosition.x+=dx;if(allowed(walkPosition.x,walkPosition.z+dz))walkPosition.z+=dz}
function readSlots(){try{const s=JSON.parse(localStorage.getItem('blockhaven-slots')||'[]');return Array.isArray(s)?s.slice(-8):[]}catch{return[]}}
function snapshotCity(){try{const slots=readSlots();slots.push({savedAt:Date.now(),city:JSON.parse(JSON.stringify(city))});localStorage.setItem('blockhaven-slots',JSON.stringify(slots.slice(-8)));updateSaveSlots();toast('City snapshot saved. Up to 8 snapshots are kept on this device.');return true}catch{toast('Snapshot could not be saved. Export the city to keep a backup.');return false}}
function updateSaveSlots(){const slots=readSlots();$('saveSlots').replaceChildren();slots.forEach((slot,index)=>{try{const saved=validateCity(slot.city),b=document.createElement('button');b.className='save-slot';b.textContent='Load '+saved.name;const note=document.createElement('small');note.textContent='Day '+saved.day+' · '+new Date(slot.savedAt).toLocaleString();b.append(note);b.onclick=()=>{if(!save()){toast('Export your current city before loading a snapshot.');return}const previous=JSON.parse(JSON.stringify(city));city=validateCity(saved);undoStack.length=0;rebuild();center();save();slots.push({savedAt:Date.now(),city:previous});try{localStorage.setItem('blockhaven-slots',JSON.stringify(slots.slice(-8)))}catch{}$('menuDialog').close();toast('Snapshot loaded. Your previous city is kept in snapshots.')};$('saveSlots').append(b)}catch{}})}
