const tourPoint=new THREE.Vector3();
function setTourPause(value){paused=value;$('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Resume simulation':'Pause simulation')}
function startTour(){$('roadSelect').value='street';$('densitySelect').value='medium';$('zoneSelect').value='home';zoneType='home';if(walkMode)exitWalk();setBuildMode('build');document.querySelectorAll('dialog[open]').forEach(d=>d.close());if(!tourActive)tourPrevious={paused,speed};tourActive=true;tourIndex=0;$('game').classList.add('tour-running');$('walkthrough').hidden=false;renderTour()}
function finishTour(completed=true){tourActive=false;tourTarget=null;$('walkthrough').hidden=true;$('tourMarker').hidden=true;$('game').classList.remove('tour-running');document.querySelectorAll('.tour-glow').forEach(e=>e.classList.remove('tour-glow'));selectTool(null);if(tourPrevious){setTourPause(tourPrevious.paused);speed=tourPrevious.speed;document.querySelectorAll('[data-speed]').forEach(b=>b.classList.toggle('active',Number(b.dataset.speed)===speed))}try{localStorage.setItem('blockhaven-walkthrough-v1','seen')}catch{}if(completed)toast('You’re ready. Replay the walkthrough anytime with ?.');$('walkthroughButton').focus()}
function findTourTarget(action){const m=metrics(city),candidates=[];for(let y=3;y<N-3;y++)for(let x=3;x<N-3;x++){const t=at(city,x,y);if(!land(x,y,city.terrain))continue;if(action==='inspect'){if(t.type==='home')candidates.push([x,y]);continue}if(t.type)continue;const a=status(city,x,y,m.roads);if(!a.road)continue;if(action!=='road'&&(!a.power||!a.water))continue;candidates.push([x,y])}return candidates.sort((a,b)=>Math.hypot(a[0]-16,a[1]-16)-Math.hypot(b[0]-16,b[1]-16))[0]||null}
function renderTour(){const step=tourSteps[tourIndex];tourDone=false;tourTarget=step.action?findTourTarget(step.action):null;document.querySelectorAll('.tour-glow').forEach(e=>e.classList.remove('tour-glow'));document.querySelectorAll(step.focus).forEach(e=>e.classList.add('tour-glow'));$('tourCounter').textContent=`Getting started · ${tourIndex+1} of ${tourSteps.length}`;$('tourDots').innerHTML=tourSteps.map((_,i)=>`<i class="${i===tourIndex?'current':i<tourIndex?'complete':''}"></i>`).join('');$('tourTitle').textContent=step.title;$('tourCopy').innerHTML=step.copy;$('tourTask').textContent=step.task;$('tourTask').classList.remove('done');$('tourBack').disabled=tourIndex===0;$('tourNext').disabled=!!step.action&&!!tourTarget;$('tourNext').textContent=tourIndex===0?'Show me':tourIndex===tourSteps.length-1?'Start building':'Next';$('tourSkipStep').hidden=!step.action||!tourTarget;$('walkthrough').classList.toggle('action-step',!!step.action);$('game').classList.toggle('tour-planning',tourIndex===8||tourIndex===9);setTourPause(tourIndex!==7);$('tourTimeStatus').textContent=tourIndex===7?'Time is running. Watch your city grow.':'Time is paused while you learn.';setBuildMode('build');selectTool(step.action&&!['inspect','zone'].includes(step.action)?step.action:null);if(step.action==='zone')setBuildMode('zone');if(tourTarget){const[px,pz]=pos(...tourTarget);target.set(px,0,pz);distance=width<720?240:210;azimuth=.8;elevation=.85;if(width<720){target.x-=Math.sin(azimuth)*26;target.z-=Math.cos(azimuth)*26}}else if(tourIndex===0||tourIndex===1)center();$('tourMarkerText').textContent=step.action==='inspect'?'Inspect this home':step.action==='zone'?'Zone here':'Build here';if(step.action&&!tourTarget){$('tourTask').textContent='No suitable free site is available in this city. You can continue, or make room with the bulldozer and replay this lesson.';$('tourNext').disabled=false}$('tourTitle').focus({preventScroll:true})}
function tourAction(action,x,y){if(!tourActive||tourDone)return;const step=tourSteps[tourIndex];if(action!==step.action)return;if(action==='inspect'&&at(city,x,y)?.type!=='home')return;const m=metrics(city),a=status(city,x,y,m.roads);if(action==='road'&&!m.roads.has(y*N+x))return;if(['home','shop','zone'].includes(action)&&(!a.road||!a.power||!a.water)){toast('Use a site with connected roads, power and water. The marked block is ready.');return}if(action==='zone'&&!at(city,x,y)?.zone)return;tourDone=true;tourTarget=null;$('tourMarker').hidden=true;$('tourTask').classList.add('done');$('tourTask').textContent=action==='road'?'✓ Road connected. Your new block is part of the town’s street network.':action==='home'?'✓ Home built with roads, power and water. Residents can move in when time runs.':action==='shop'?'✓ Shop built. That’s 32 more jobs for your growing neighborhood.':action==='zone'?'✓ Residential district painted. Let time run and developers will build it.':'✓ Home inspected. Missing services show an open circle; supplied services show a check.';$('tourNext').disabled=false;$('tourSkipStep').hidden=true}
function positionTourMarker(){if(!tourActive||!tourTarget){$('tourMarker').hidden=true;return}const[px,pz]=pos(...tourTarget);tourPoint.set(px,1,pz).project(camera);$('tourMarker').hidden=tourPoint.z>1||Math.abs(tourPoint.x)>1||Math.abs(tourPoint.y)>1;$('tourMarker').style.left=((tourPoint.x+1)*width/2)+'px';$('tourMarker').style.top=((1-tourPoint.y)*height/2)+'px';tileHighlight.visible=true;tileHighlight.position.set(px,.6,pz);tileHighlight.material.color.set('#f4cb72')}
$('tourNext').onclick=()=>{if(tourIndex===tourSteps.length-1)finishTour();else{tourIndex++;renderTour()}};$('tourBack').onclick=()=>{if(tourIndex>0){tourIndex--;renderTour()}};$('tourSkipStep').onclick=()=>{tourIndex++;renderTour()};$('tourExit').onclick=()=>finishTour(false);$('walkthroughButton').onclick=startTour;$('replayTourButton').onclick=startTour;
let tourSeen=false;try{tourSeen=localStorage.getItem('blockhaven-walkthrough-v1')==='seen'}catch{}if(!tourSeen)startTour();

function animate(ms){if(graphicsLost)return;requestAnimationFrame(animate);const dt=Math.min((ms-last)/1000,.1);last=ms;const modal=!!document.querySelector('dialog[open]'),running=!paused&&!modal&&(!tourActive||tourIndex===7);if(running){elapsed+=dt*speed;while(elapsed>=6){elapsed-=6;const changes=tick(city);changes.forEach(i=>createBlock(i%N,Math.floor(i/N),true));if(changes.length){makeCars();updateLayer()}if(changes.grant){toast('Milestone reached! '+changes.grant.toLocaleString()+' residents. $3,000 grant awarded.');visual.particles(target.x,18,target.z,'celebrate',70)}changed();updateUI()}}
 visual.update(dt,speed,running,elapsed/6);if(walkMode){updateWalking(dt,modal);camera.position.copy(walkPosition);camera.lookAt(walkPosition.x+Math.sin(walkYaw)*10,walkPosition.y+Math.sin(walkPitch)*10,walkPosition.z+Math.cos(walkYaw)*10)}else{camera.position.set(target.x+distance*Math.cos(elevation)*Math.sin(azimuth),distance*Math.sin(elevation),target.z+distance*Math.cos(elevation)*Math.cos(azimuth));camera.lookAt(target)}camera.updateMatrixWorld();positionTourMarker();renderer.render(scene,camera);if(!$('bootStatus').hidden)$('bootStatus').hidden=true;if(frame++%30===0){const r=visual.stats();$('renderStats').textContent=`${r.fps} fps · ${r.drawCalls.toLocaleString()} draws · ${Math.round(r.triangles/1000)}k triangles`;$('sceneTime').textContent=settings.lighting==='night'?'After dark':settings.lighting==='sunset'?'Golden hour':settings.lighting==='cycle'?'Day / night cycle':'Daylight'}}visual.update(.001,speed,false);renderer.compileAsync(scene,camera).then(()=>requestAnimationFrame(animate)).catch(e=>{$('bootMessage').textContent='The 3D scene did not finish loading. Try low graphics or reload the page.';console.error(e)});canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();graphicsLost=true;$('bootStatus').hidden=false;$('bootMessage').textContent='The graphics connection was interrupted. Reload the page or try low graphics; your saved city stays on this device.'});
